async function seedCustomers() {
  try {
    logger.info('🔄 Starting customer seeding...');

    // Delete existing customers
    // await prisma.customer.deleteMany();
    // logger.info('🗑️ Cleared existing customers');

    // Check if carigars already exist
    const existingCount = await prisma.customer.count();
    
    if (existingCount > 0) {
      logger.info(`Found ${existingCount} existing customers. Skipping seed.`);
      return;
    }

    // Create customers
    for (const customerData of customersData) {
      await prisma.customer.create({
        data: customerData
      });
    }

    logger.info(`✅ Successfully seeded ${customersData.length} customers`);
  } catch (error) {
    logger.error('❌ Error seeding customers:', error);
    throw error;
  }
}

async function main() {
  try {
    await seedCarigars();
    await seedGoldArticles();
    await seedCustomers();
    logger.info('🎉 Database seeding completed successfully');
  } catch (error) {
    logger.error('💥 Database seeding failed:', error);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

